<template>
  <article class="safety-document" :style="{'--plan-color':branding?.color||'#175b48',fontFamily:`${branding?.font||'Montserrat'}, Arial, sans-serif`}">
    <header><img v-if="logo&&!logoFailed" :src="logo" @error="logoFailed=true" referrerpolicy="no-referrer" :alt="branding?.name" /><div><p>{{ branding?.name }}</p><h2>{{ modelValue.documentName||template.title }}</h2><p v-if="modelValue.documentName">{{ template.title }}</p><p v-if="version">Version {{ version }}</p></div><span class="auricwell-brand"><img src="/auricwell/mark.svg" alt="" />AuricWell EHR</span></header><p v-if="template.description" class="document-description">{{ template.description }}</p>
    <p v-if="template.key==='release-of-information'" class="document-description">I authorize {{ branding.name }} to release and exchange only the information specified below with the named recipient, for the stated purpose and duration.</p><label v-if="editable" class="document-name">Document name<input aria-label="Document name" :value="modelValue.documentName" :placeholder="template.title" maxlength="160" @input="set('documentName',$event.target.value)" /></label><div class="plan-basics"><label>Client / individual<input v-if="editable" :value="modelValue.personLabel" maxlength="200" @input="set('personLabel',$event.target.value)" /><strong v-else>{{ modelValue.personLabel }}</strong></label><label>{{ template.key==='safety-plan'?'Plan date':'Document date' }}<input v-if="editable" type="date" :value="modelValue.planDate" @input="set('planDate',$event.target.value)" /><span v-else>{{ modelValue.planDate || 'Not recorded' }}</span></label><label v-if="template.key==='safety-plan'">Next review<input v-if="editable" type="date" :value="modelValue.reviewDate" @input="set('reviewDate',$event.target.value)" /><span v-else>{{ modelValue.reviewDate || 'Not recorded' }}</span></label></div>
    <p v-if="template.key==='cssrs-screener' && screenConcern" class="screen-concern" role="status">{{ screenConcern }}</p>
    <section v-for="section in template.sections" :key="section.title"><h3>{{ section.title }}</h3>
      <div class="form-field" v-for="[key,label,spec={}] in visibleFields(section)" :key="key"><span>{{ label }}</span>
       <small v-if="spec.helperText">{{ spec.helperText }}</small><template v-if="editable">
        <span v-if="spec.type==='radio'" class="radio-options" role="group" :aria-label="label"><label v-for="option in spec.options" :key="option.value" class="check-option"><input type="radio" :name="key" :value="option.value" :checked="modelValue[key]===option.value" @change="set(key,option.value)" />{{ option.label }}</label><button v-if="modelValue[key]" type="button" :aria-label="`Clear answer: ${label}`" @click="set(key,'')">Clear</button></span>
        <span v-else-if="spec.type==='multi'" class="option-list"><label v-for="option in spec.options" :key="option.value||option" class="check-option"><input type="checkbox" :checked="(modelValue[key]||[]).includes(option.value||option)" @change="toggle(key,option.value||option,$event.target.checked)" />{{ option.label||option }}</label></span>
        <select :aria-label="label" v-else-if="spec.type==='select'" :value="modelValue[key]||''" @change="set(key,$event.target.value)"><option value="">Choose…</option><option v-for="option in spec.options" :key="option.value||option" :value="option.value||option">{{ option.label||option }}</option></select>
        <input v-else-if="spec.type&&spec.type!=='textarea'" :type="spec.type" :value="modelValue[key]" :aria-label="label" maxlength="6000" @input="set(key,$event.target.value)" />
        <textarea v-else :value="modelValue[key]" rows="3" :aria-label="label" maxlength="6000" @input="set(key,$event.target.value)" />
       </template><p v-else class="answer">{{ answer(modelValue[key],spec) }}</p>
      </div><p v-if="section.notice" class="document-notice">{{ section.notice }}</p>
      <template v-if="section.repeat"><div v-for="(row,i) in modelValue[section.repeat]||[]" :key="i" class="contact-row"><label v-for="[key,label] in section.columns" :key="key">{{ label }}<input v-if="editable" :value="row[key]" :type="key==='phone'?'tel':'text'" maxlength="1000" @input="setContact(section.repeat,i,key,$event.target.value)" /><span v-else>{{ row[key] || '—' }}</span></label><button v-if="editable" type="button" :aria-label="`Remove contact ${i+1} from ${section.title}`" @click="remove(section.repeat,i)">Remove</button></div><button v-if="editable && (modelValue[section.repeat]?.length||0)<12" type="button" @click="add(section)">Add contact</button></template>
    </section>
    <aside v-if="template.crisis" class="crisis"><strong>{{ template.crisis.text }}</strong><a :href="template.crisis.url" target="_blank" rel="noopener noreferrer">988 support information</a><p>Build this plan together with the care team. Signing records participation; it is not a promise that a crisis cannot occur.</p></aside>
    <section v-if="template.key==='attendance-verification'&&!editable" class="attendance-letter"><h3>Attendance letter</h3><p>To whom it may concern:</p><p v-if="modelValue.attendanceStatus==='Confirmed attended'">{{ modelValue.personLabel }} attended an appointment with {{ branding.name }} on {{ modelValue.appointmentDate }} from {{ modelValue.startTime }} to {{ modelValue.endTime }} ({{ modelValue.timezone }}) at {{ modelValue.location }}.</p><p v-else>Attendance has not yet been confirmed. This draft does not verify attendance.</p><p v-if="modelValue.excuseRequested==='Yes'">Please excuse their absence from school or work for this appointment<span v-if="modelValue.absenceFrom&&modelValue.absenceThrough">, from {{ modelValue.absenceFrom }} to {{ modelValue.absenceThrough }}</span>.</p><p>{{ modelValue.issuerName }} · {{ modelValue.issuerTitle }}<br />{{ branding.name }}<br />{{ modelValue.contactPhone }}</p><p v-if="!signers.some(s=>s.kind==='clinician'&&s.signedAt)"><strong>Draft · Not yet signed by issuing staff</strong></p></section>
    <section v-if="signers.length"><h3>Signatures for version {{ version }}</h3><div v-for="s in signers" :key="s.id" class="signature-receipt"><strong>{{ s.name }} · {{ s.kind==='clinician'?'Staff':s.kind }}</strong><template v-if="s.signedAt"><img :src="s.evidence?.signature" :alt="`Signature of ${s.evidence?.name||s.name}`" /><p>{{ s.evidence?.name }} · {{ displayDate(s.signedAt) }} · {{ s.method==='in_person'?'Signed together with a staff witness':s.method==='portal'?'Signed in the secure portal':'Signed by staff' }}</p></template><p v-else>{{ s.revokedAt?'Access withdrawn':s.copyOnly?'Shared copy · No signature required':'Awaiting signature' }}</p></div></section>
    <footer><p>AuricWell · {{ branding?.name }} · {{ template.title }}<span v-if="version"> · Version {{ version }}</span></p><a v-for="reference in template.references||[]" :key="reference.url" :href="reference.url" target="_blank" rel="noopener noreferrer">{{ reference.title }}</a></footer>
  </article>
</template>
<script setup>
import {computed,ref,watch} from 'vue';
import {toUploadsUrl} from '../../utils/uploadsUrl';
const props=defineProps({modelValue:{type:Object,required:true},template:{type:Object,required:true},branding:Object,editable:Boolean,version:Number,signers:{type:Array,default:()=>[]}});
const logoFailed=ref(false);
watch(()=>props.branding?.logoUrl,()=>{logoFailed.value=false;});
const emit=defineEmits(['update:modelValue']);
const logo=computed(()=>{const url=props.branding?.logoUrl||'';return url?toUploadsUrl(url):'';});
function answer(value,spec){const label=v=>(spec.options||[]).find(o=>o.value===v)?.label||v;return Array.isArray(value)?value.map(label).join('; ')||'Not provided':label(value)||'Not provided';}
function toggle(key,value,checked){set(key,checked?[...(props.modelValue[key]||[]),value]:(props.modelValue[key]||[]).filter(v=>v!==value));}
function visibleFields(section){return (section.fields||[]).filter(([, , spec={}])=>!spec.showIf||props.modelValue[spec.showIf.fieldKey]===spec.showIf.equals);}
const screenConcern=computed(()=>{
 const d=props.modelValue;
 if((d.cssrs_2==='yes'&&(d.cssrs_4==='yes'||d.cssrs_5==='yes'))||(d.cssrs_6==='yes'&&d.cssrs_6_recent==='yes'))return 'Prompt safety follow-up needed. Follow your agency’s crisis procedure now and document the actions taken. Saving this form does not send an alert.';
 if(d.cssrs_1==='yes'||d.cssrs_2==='yes'||d.cssrs_6==='yes')return 'Review the reported thoughts or behavior with the individual and document the clinical response and follow-up.';
 return '';
});
function set(key,value){const next={...props.modelValue,[key]:value};for(const section of props.template.sections)for(const [field,,spec={}] of section.fields||[])if(spec.showIf&&next[spec.showIf.fieldKey]!==spec.showIf.equals)next[field]='';emit('update:modelValue',next);}
function setContact(list,i,key,value){set(list,props.modelValue[list].map((r,j)=>i===j?{...r,[key]:value}:r));}
function add(section){set(section.repeat,[...(props.modelValue[section.repeat]||[]),Object.fromEntries(section.columns.map(([key])=>[key,'']))]);}
function remove(list,i){set(list,props.modelValue[list].filter((_,j)=>i!==j));}
const displayDate=value=>new Date(value).toLocaleString();
</script>
<style scoped>
.safety-document{--plan-color:#175b48;background:#fff;border:1px solid #dbe4e0;border-radius:16px;overflow:hidden;color:#233c35}.safety-document header{display:flex;align-items:center;gap:22px;padding:30px;background:color-mix(in srgb,var(--plan-color) 8%,white);border-top:7px solid var(--plan-color)}header img{width:95px;max-height:110px;object-fit:contain}h2{font-size:30px;margin:8px 0}header p{margin:0;font-size:13px}.plan-basics{display:grid;grid-template-columns:2fr 1fr 1fr;gap:18px;padding:24px}section{padding:20px 24px;border-top:1px solid #e1e8e4}h3{font-size:17px;margin:0 0 20px;color:var(--plan-color)}label{display:grid;gap:8px;font-size:13px;font-weight:600;margin-bottom:16px}input,textarea{font:inherit;font-weight:400;line-height:1.6;padding:11px;border:1px solid #b8cdc3;border-radius:6px;background:#fbfdfc;color:#233c35;min-width:0;width:100%;box-sizing:border-box}textarea{resize:vertical}.answer{white-space:pre-wrap;overflow-wrap:anywhere;font-weight:400;line-height:1.8;margin:0}.contact-row{display:grid;grid-template-columns:1fr 1fr 1.5fr auto;gap:12px;align-items:center}button{font:inherit;padding:9px 12px;background:#edf4ef;border:1px solid #b8cdc3;border-radius:6px;cursor:pointer}.crisis{background:#f5f1e6;padding:24px;font-size:13px;line-height:1.8}.crisis a{display:block;color:var(--plan-color)}.signature-receipt{padding:14px 0;border-bottom:1px solid #dbe4e0}.signature-receipt img{display:block;max-width:250px;max-height:90px}.signature-receipt p{font-size:12px}@media(max-width:700px){.plan-basics,.contact-row{grid-template-columns:1fr}section{padding:18px}header{padding:20px!important}}
.radio-options{display:flex;align-items:center;gap:16px}.radio-options label{margin:0;padding:10px 16px;border:1px solid #b8cdc3;border-radius:7px;cursor:pointer}.radio-options input{width:20px;height:20px;accent-color:var(--plan-color)}.form-field small{font-weight:400;color:#536c60}.screen-concern{margin:20px;padding:16px;border-left:4px solid #a44528;background:#fff2e9;line-height:1.7}.auricwell-brand{margin-left:auto;display:flex;align-items:center;gap:8px;font-size:12px;white-space:nowrap}.auricwell-brand img{width:26px;height:30px}.document-description,.document-notice{line-height:1.8;padding:0 24px;font-size:13px}.document-notice{padding:0}.check-option{display:flex;align-items:flex-start;font-weight:400}.check-option input{width:auto}.form-field{display:grid;gap:8px;margin-bottom:16px;font-size:13px;font-weight:600}.option-list{display:grid;gap:3px}select{font:inherit;padding:12px;border:1px solid #b8cdc3;border-radius:6px;max-width:100%}footer{padding:20px 24px;font-size:12px}footer a{display:block}.attendance-letter p{line-height:1.8}@media(max-width:600px){.auricwell-brand{margin-left:0}.safety-document header{flex-wrap:wrap}}
</style>
